		function bunyi_klakson(){
		  this.btn_klakson_on.visible=false;
		  this.btn_klakson_off.visible=true;
		  if(this.k_horn1.visible==true&& this.k_horn1.visible==true && this.k_horn2.visible==true&& this.k_horn3.visible==true&& this.k_horn4.visible==true&& this.k_horn5.visible==true&& this.k_horn6.visible==true&& this.k_horn7.visible==true){createjs.Sound.play("klakson","none", 0, 0, -1, 0.5)};
		  if(this.k_horn2.visible==true&& this.k_horn3.visible==true&& this.k_horn6.visible==true&&  this.k_horn7.visible==true ){this.relay_c.tuas.rotation= 0;this.relay_c.magnet.visible= true}}
		
		/*music is the instance name
		"none' is the interrupt
		0 is delay
		0 is offset
		-1 is loop 0 is no loop
		0.5 is the volume*/
		  
		function bunyi_klakson_off(){
		  this.btn_klakson_off.visible=false;
		  this.btn_klakson_on.visible=true;
			if(this.k_horn1.visible==true&& this.k_horn1.visible==true && this.k_horn2.visible==true&& this.k_horn3.visible==true&& this.k_horn4.visible==true&& this.k_horn5.visible==true&& this.k_horn6.visible==true&& this.k_horn7.visible==true){createjs.Sound.stop("klakson","none", 0, 0, 0, 0)};
			if(this.k_horn2.visible==true&& this.k_horn3.visible==true&& this.k_horn6.visible==true&&  this.k_horn7.visible==true ){this.relay_c.tuas.rotation= -45;this.relay_c.magnet.visible= false}
		}
